/*
  шахматы.js — ДОСКА И ПРАВИЛА.

  Правила берёт готовая библиотека chess.js 1.4.0, лицензия
  BSD-2-Clause: свободная, коммерческое использование разрешено, GPL
  здесь нет. Файл лежит рядом (chess.js) и никуда не ходит по сети.

  Доска нарисована своя, под оформление мира. Соперника-машины нет
  намеренно: человек ходит за обе стороны, этого хватает, чтобы
  проверить правила, и это снимает вопрос с лицензиями сильных движков.

  Чем отличается от соседей: ход.js занимается миром и переходами и о
  шахматах знает только то, что отдано наружу через window.ШАХМАТЫ.
  Текстов здесь нет — они берутся из мир.js, числа из настройки.js.
*/

import { Chess } from './chess.76c7c34f.js';

/*  Свои имена данных. Сборка героя и мир живут теперь на одном адресе,
    и общих НАСТРОЙКИ и МИР там быть не может — каждая часть держит
    своё. Доска берёт настройки и слова мира.                        */
const НАСТРОЙКИ = window.МИР_НАСТРОЙКИ;
const МИР       = window.МИР_ДАННЫЕ;

const БУКВЫ = ['a', 'b', 'c', 'd', 'e', 'f', 'g', 'h'];

/* У каждого стола своя партия. Одна общая означала бы, что человек
   открывает соседний стол и видит там чужую позицию, — мир не должен
   меняться под ним. Ключ приходит снаружи, из ход.js. */
const партии = new Map();

let игра = null;
let ключПартии = null;
let выбрана = null;          // с какой клетки собираемся ходить
let место = null;            // куда рисуем
let сообщить = null;         // чем сказать миру, что ход сделан

/* Белые — нулевое место за столом, чёрные — первое. */
function чейХод() {
  return (игра && игра.turn() === 'w') ? 0 : (игра ? 1 : 0);
}

function клеткаПоНомеру(столбец, строка) {
  return БУКВЫ[столбец] + (НАСТРОЙКИ.шахматы.клеток - строка);
}

function ходыИз(клетка) {
  return игра.moves({ square: клетка, verbose: true });
}

function нарисовать() {
  const н = НАСТРОЙКИ.шахматы;
  const возможные = выбрана ? ходыИз(выбрана).map((х) => х.to) : [];
  const бьющие = выбрана
    ? ходыИз(выбрана).filter((х) => х.captured).map((х) => х.to) : [];

  let разметка = '<div class="доска">';
  for (let строка = 0; строка < н.клеток; строка++) {
    for (let столбец = 0; столбец < н.клеток; столбец++) {
      const имя = клеткаПоНомеру(столбец, строка);
      const фигура = игра.get(имя);
      const классы = ['клетка', (строка + столбец) % 2 === 0 ? 'светлая' : 'тёмная'];
      if (имя === выбрана) классы.push('выбрана');
      if (возможные.includes(имя)) classesДобавить(классы, бьющие.includes(имя));
      if (фигура) классы.push(фигура.color === 'w' ? 'белая-фигура' : 'чёрная-фигура');
      разметка += '<div class="' + классы.join(' ') + '" data-клетка="' + имя + '">' +
        (фигура ? '<span class="фигура">' + н.фигуры[фигура.type] + '</span>' : '') +
        '</div>';
    }
  }
  разметка += '</div><div class="итог-партии">' + строкаИтога() + '</div>';
  место.innerHTML = разметка;

  if (игра.isGameOver()) {
    const кн = document.createElement('button');
    кн.className = 'кн тихая';
    кн.textContent = МИР.тексты.шахматы_заново;
    кн.addEventListener('click', заново);
    место.appendChild(кн);
  }

  function classesДобавить(классы, бьёт) {
    классы.push('можно');
    if (бьёт) классы.push('занята');
  }
}

function строкаИтога() {
  const т = МИР.тексты;
  if (игра.isCheckmate()) {
    // мат ставит тот, чья очередь НЕ настала
    const победили = игра.turn() === 'w' ? т.шахматы_чёрные : т.шахматы_белые;
    return подставитьЗдесь(т.шахматы_мат, { кто: победили });
  }
  if (игра.isStalemate()) return т.шахматы_пат;
  if (игра.isDraw()) return т.шахматы_ничья;
  if (игра.inCheck()) return т.шахматы_шах;
  return '';
}

// маленькая своя подстановка: тянуть её из ход.js ради одной строки незачем
function подставитьЗдесь(шаблон, значения) {
  return шаблон.replace(/\{([^{}]+)\}/g, (всё, ключ) =>
    (ключ in значения) ? значения[ключ] : всё);
}

function нажали(имяКлетки) {
  if (игра.isGameOver()) return;

  if (выбрана) {
    const ход = ходыИз(выбрана).find((х) => х.to === имяКлетки);
    if (ход) { сделать(ход); return; }
  }
  const фигура = игра.get(имяКлетки);
  выбрана = (фигура && фигура.color === игра.turn()) ? имяКлетки : null;
  нарисовать();
}

function сделать(ход) {
  if (ход.promotion) { спроситьПревращение(ход); return; }
  игра.move({ from: ход.from, to: ход.to });
  выбрана = null;
  нарисовать();
  if (сообщить) сообщить();
}

/* Превращение пешки: спрашиваем, во что. Окошко общее, из ход.js. */
function спроситьПревращение(ход) {
  const т = МИР.тексты;
  const подписи = {
    q: т.шахматы_ферзь, r: т.шахматы_ладья,
    b: т.шахматы_слон,  n: т.шахматы_конь
  };
  const кнопки = НАСТРОЙКИ.шахматы.превращение.map((буква, номер) =>
    [подписи[буква], () => {
      игра.move({ from: ход.from, to: ход.to, promotion: буква });
      выбрана = null;
      нарисовать();
      if (сообщить) сообщить();
    }, номер === 0]);
  window.ОКОШКО(т.шахматы_превращение, '', кнопки);
}

function заново() {
  игра = new Chess();
  партии.set(ключПартии, игра);
  выбрана = null;
  нарисовать();
  if (сообщить) сообщить();
}

/* Единственная дверь наружу: ход.js знает только это. */
window.ШАХМАТЫ = {
  чейХод: чейХод,
  поставить: function (узел, приХоде, ключ) {
    место = узел;
    сообщить = приХоде;
    ключПартии = ключ;
    if (!партии.has(ключ)) партии.set(ключ, new Chess());
    игра = партии.get(ключ);
    выбрана = null;
    узел.onclick = (с) => {
      const клетка = с.target.closest('[data-клетка]');
      if (клетка) нажали(клетка.dataset.клетка);
    };
    нарисовать();
  },
  заново: заново
};
